/* Apply measured list geometry only where the existing renderer has matching controls.
   The controls themselves retain their original handlers, state and local persistence. */
(()=>{'use strict';
 const q=new URLSearchParams(location.search),tenant=q.get('tenant'),route=q.get('route'),p=window.AdminCurrentListLayout?.[tenant+'/'+route];if(!p)return;
 const norm=s=>window.Admin.uiText(String(s||'')).replace(/选择所有行|选择当前页/g,'').replace(/\s+/g,'').trim();
 const px=n=>n+'px';let pending=false;
 function apply(){pending=false;const root=document.querySelector('#app>.table-page');if(!root)return;
  const table=root.querySelector('.table-wrap table'),panel=root.querySelector(':scope>.filter-panel'),toolbar=root.querySelector('.source-toolbar');if(!table||!panel||!toolbar)return;
  const headers=[...table.querySelectorAll('thead th')];if(headers.length!==p.columns.length||headers.some((h,i)=>norm(h.textContent)!==norm(p.columns[i].label)))return;
  const cols=[...table.querySelectorAll('colgroup col')];if(cols.length===p.columns.length){cols.forEach((c,i)=>c.style.width=px(p.columns[i].width));table.style.width=px(p.columns.reduce((n,c)=>n+c.width,0));}
  // At other widths retain the normal wrapping layout. The source captures are not a
  // basis for inventing a second responsive breakpoint or moving unseen controls.
  if(Math.abs(innerWidth-p.width)>2){root.classList.remove('current-list-measured');return;}
  // Some source account pickers are rendered by a custom component with no input
  // node. Restore its captured label using the existing tenant-local select helper.
  for(const ref of p.fields.filter(f=>['微信号','微信人设'].includes(f.label)&&!f.controls?.length))if(![...panel.querySelectorAll(':scope>.field')].some(f=>norm(f.querySelector(':scope>span')?.textContent)===norm(ref.label))){const field=document.createElement('div'),label=document.createElement('span'),select=document.createElement('select');field.className='field';label.textContent=ref.label;select.dataset.filter=ref.label==='微信人设'?'人设':ref.label;select.setAttribute('aria-label',ref.label);select.append(new Option('请选择',''));window.Admin.optionsFor(ref.label==='微信人设'?'人设':ref.label).forEach(value=>select.append(new Option(value,value)));field.append(label,window.Admin.searchableSelect(select,ref.label));panel.prepend(field);}
  const fields=[...panel.querySelectorAll(':scope>.field')],fieldPairs=[],usedFields=new Set();
  for(const f of fields){const label=norm(f.querySelector(':scope>span')?.textContent),placeholders=[...f.querySelectorAll('input')].map(c=>norm(c.placeholder)).filter(Boolean);let index=p.fields.findIndex((x,i)=>!usedFields.has(i)&&label&&norm(x.label)===label);if(index<0)index=p.fields.findIndex((x,i)=>!usedFields.has(i)&&!x.label&&x.controls?.some(c=>c.placeholder&&placeholders.includes(norm(c.placeholder))));if(index<0&&!label)index=p.fields.findIndex((x,i)=>!usedFields.has(i)&&!x.label);if(index<0){root.dataset.currentLayoutSkipped='unmatched field: '+label;return;}usedFields.add(index);fieldPairs.push([f,p.fields[index]]);}
  if(fieldPairs.length!==p.fields.length){root.dataset.currentLayoutSkipped='missing captured fields';return;}
  const buttons=[...panel.querySelectorAll('.filter-actions>button,.quick-dates>button'),...toolbar.querySelectorAll(':scope>button')],buttonPairs=[];const used=new Set();
  for(const b of buttons){const i=p.buttons.findIndex((x,i)=>!used.has(i)&&norm(x.text)===norm(b.textContent));if(i<0){root.dataset.currentLayoutSkipped='unmatched button: '+norm(b.textContent);return;}used.add(i);buttonPairs.push([b,p.buttons[i]]);}
  if(used.size!==p.buttons.length){root.dataset.currentLayoutSkipped='missing captured buttons: '+p.buttons.filter((_,i)=>!used.has(i)).map(b=>b.text).join(',');return;}
  delete root.dataset.currentLayoutSkipped;
  root.classList.add('current-list-measured');if(!root.querySelector(':scope>.current-list-stage')){const stage=document.createElement('div');stage.className='current-list-stage';stage.setAttribute('aria-hidden','true');root.prepend(stage);}root.style.setProperty('--current-head-height',px(p.table.y));root.style.setProperty('--current-table-left',px(p.table.x));root.style.setProperty('--current-table-right',px(Math.max(0,p.width-p.table.x-p.table.width)));
  const stage=root.querySelector(':scope>.current-list-stage');if(!stage.dataset.decorated){stage.dataset.decorated='true';for(const ref of p.headings||[]){const title=document.createElement('h2');title.textContent=ref.text;Object.assign(title.style,{position:'absolute',margin:'0',left:px(ref.rect.x),top:px(ref.rect.y),fontSize:ref.fontSize,lineHeight:ref.lineHeight,fontWeight:ref.fontWeight,color:ref.color});stage.append(title);}if(p.description){const note=document.createElement('p');note.className='current-source-description';note.textContent=p.description;stage.append(note);}if(p.medicalTop){const block=document.createElement('section');block.className='current-medical-top';p.medicalTop.forEach((text,index)=>{const line=document.createElement(index?'p':'strong');line.textContent=text;block.append(line);});stage.append(block);}if(route==='entList'){const heading=document.createElement('strong');heading.className='current-environment-title';heading.textContent='环境管理 ('+p.renderedRowCount+')';stage.append(heading);}if(stage.children.length)stage.removeAttribute('aria-hidden');}
  for(const [f,ref] of fieldPairs){Object.assign(f.style,{left:px(ref.rect.x),top:px(ref.rect.y),width:px(ref.rect.width),height:px(ref.rect.height),paddingTop:ref.paddingTop,paddingBottom:ref.paddingBottom});const label=f.querySelector(':scope>span');if(label)label.style.flexShrink='0';}
  for(const [b,ref] of buttonPairs){Object.assign(b.style,{left:px(ref.rect.x),top:ref.footer?'auto':px(ref.rect.y),bottom:ref.footer?px(ref.bottom):'auto',width:px(ref.rect.width),height:px(ref.rect.height),fontSize:ref.fontSize});if(ref.text==='重置'&&ref.rect.width<70)b.querySelector('.button-icon')?.remove();}
  if(p.footerHeight>20&&p.footerHeight<100){root.style.setProperty('--current-table-height','calc(100vh - '+px(p.table.y+p.footerHeight)+')');root.style.setProperty('--current-footer-height',px(p.footerHeight));root.classList.add('current-list-fill');}
  const sourceEmpty=p.renderedRowCount===0&&!table.querySelector('tbody tr');root.classList.toggle('current-source-empty',sourceEmpty);if(sourceEmpty){root.style.setProperty('--current-empty-height',px(p.table.height));const emptyCell=table.closest('.table-wrap').querySelector(':scope>.empty');if(emptyCell&&emptyCell.textContent!=='暂无数据')emptyCell.textContent='暂无数据';}
  if(p.footerHeight<=20&&p.table.height>500){root.style.setProperty('--current-table-height','calc(100vh - '+px(p.table.y+48)+')');root.classList.add('current-list-fill');}
  headers.forEach((h,i)=>{h.style.height=px(p.columns[i].headerHeight);h.style.textAlign=p.columns[i].align;h.style.fontWeight=p.columns[i].fontWeight;h.style.fontSize=p.columns[i].fontSize;h.style.color=p.columns[i].color;if(p.columns[i].pinnedRight){h.classList.add('current-source-pinned');table.querySelectorAll('tbody tr').forEach(r=>r.children[i]?.classList.add('current-source-pinned'));}});
 }
 function schedule(){if(pending)return;pending=true;requestAnimationFrame(apply)}
 new MutationObserver(schedule).observe(document.getElementById('app'),{childList:true,subtree:true});window.addEventListener('resize',schedule);schedule();
})();
